class Currency { final String code, nameAr, nameEn, symbol; final int decimalDigits; Currency({required this.code, required this.nameAr, required this.nameEn, required this.symbol, this.decimalDigits=2}); String name(bool ar) => ar ? nameAr : nameEn; }
class CurrencyCatalog { static final all = <Currency>[
 Currency(code:'YER',nameAr:'ريال يمني',nameEn:'Yemeni Rial',symbol:'﷼',decimalDigits:0), Currency(code:'SAR',nameAr:'ريال سعودي',nameEn:'Saudi Riyal',symbol:'﷼'), Currency(code:'AED',nameAr:'درهم إماراتي',nameEn:'UAE Dirham',symbol:'د.إ'), Currency(code:'KWD',nameAr:'دينار كويتي',nameEn:'Kuwaiti Dinar',symbol:'د.ك',decimalDigits:3), Currency(code:'QAR',nameAr:'ريال قطري',nameEn:'Qatari Riyal',symbol:'ر.ق'), Currency(code:'BHD',nameAr:'دينار بحريني',nameEn:'Bahraini Dinar',symbol:'د.ب',decimalDigits:3), Currency(code:'OMR',nameAr:'ريال عماني',nameEn:'Omani Rial',symbol:'ر.ع',decimalDigits:3), Currency(code:'USD',nameAr:'دولار أمريكي',nameEn:'US Dollar',symbol:'\$'), Currency(code:'EUR',nameAr:'يورو',nameEn:'Euro',symbol:'€'), Currency(code:'GBP',nameAr:'جنيه إسترليني',nameEn:'British Pound',symbol:'£'), Currency(code:'JPY',nameAr:'ين ياباني',nameEn:'Japanese Yen',symbol:'¥',decimalDigits:0), Currency(code:'CNY',nameAr:'يوان صيني',nameEn:'Chinese Yuan',symbol:'¥'), Currency(code:'TRY',nameAr:'ليرة تركية',nameEn:'Turkish Lira',symbol:'₺'), Currency(code:'EGP',nameAr:'جنيه مصري',nameEn:'Egyptian Pound',symbol:'ج.م'), Currency(code:'INR',nameAr:'روبية هندية',nameEn:'Indian Rupee',symbol:'₹'), Currency(code:'CAD',nameAr:'دولار كندي',nameEn:'Canadian Dollar',symbol:'CA\$'), Currency(code:'AUD',nameAr:'دولار أسترالي',nameEn:'Australian Dollar',symbol:'A\$'), Currency(code:'CHF',nameAr:'فرنك سويسري',nameEn:'Swiss Franc',symbol:'CHF'), ]; static Currency byCode(String c) => all.firstWhere((x)=>x.code==c, orElse:()=>all.first); }
